import React from 'react';
import './Predefined.css';
import axios from 'axios';
import { Link } from 'react-router-dom';

function Predefined() {
  const triggerPattern = async (patternNumber) => {
    try {
      await axios.post('http://localhost:8000/set_pattern', { pattern_id: patternNumber });
      console.log('Pattern sent:', patternNumber);
    } catch (error) {
      console.error('Error:', error);
    }
  };

  return (
    <>
      <header>
        <div className="logo">
          <h1>SonicGLow<br />Cube</h1>
        </div>
        <nav>
          <ul>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/resources">Resources</Link></li>
            <li><Link to="/cube">SonicGlow Cube</Link></li>
            <li><Link to="/about" className="active">About Us</Link></li>
          </ul>
        </nav>
      </header>

      <main>
        <div className="pattern-grid">
          {[...Array(10)].map((_, index) => (
            <button
              key={index}
              className="pattern-box"
              onClick={() => triggerPattern(index + 1)}
            >
              <span>Pattern {String(index + 1).padStart(2, '0')}</span>
            </button>
          ))}
        </div>
      </main>
    </>
  );
}

export default Predefined;
